-- Guias da Bolsa (Operação › Guias): páginas com link público /g/<slug>.
create table if not exists public.guides (
  id uuid primary key default gen_random_uuid(),
  agency_id integer not null references public.agencies(id) on delete cascade,
  slug text not null unique check (slug ~ '^[a-z0-9-]{3,80}$'),
  title text not null,
  audience text not null default 'cliente' check (audience in ('socio','cliente','equipe')),
  language text not null default 'pt' check (language in ('pt','en','es')),
  services text[] not null default '{}',
  content jsonb not null,
  version integer not null default 1,
  is_published boolean not null default true,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.guide_versions (
  id uuid primary key default gen_random_uuid(),
  guide_id uuid not null references public.guides(id) on delete cascade,
  version integer not null,
  content jsonb not null,
  instructions text,
  created_by uuid,
  created_at timestamptz not null default now()
);
create index if not exists guide_versions_guide_idx on public.guide_versions(guide_id, version desc);

alter table public.guides enable row level security;
alter table public.guide_versions enable row level security;

-- Link público: qualquer pessoa lê um guia publicado (é para mandar a quem quiser).
create policy guides_public_read on public.guides for select to anon, authenticated using (is_published);
-- Equipe da agência vê tudo (rascunhos também) e edita.
create policy guides_staff_read on public.guides for select to authenticated using (agency_id = any(app.staff_agencies()));
create policy guides_staff_insert on public.guides for insert to authenticated with check (agency_id = any(app.staff_agencies()));
create policy guides_staff_update on public.guides for update to authenticated using (agency_id = any(app.staff_agencies())) with check (agency_id = any(app.staff_agencies()));
create policy guides_staff_delete on public.guides for delete to authenticated using (agency_id = any(app.staff_agencies()));
create policy guide_versions_staff on public.guide_versions for select to authenticated
  using (exists (select 1 from public.guides g where g.id = guide_id and g.agency_id = any(app.staff_agencies())));

grant select on public.guides to anon;
grant select, insert, update, delete on public.guides to authenticated;
grant select on public.guide_versions to authenticated;

-- Primeiro guia: o onboarding de cliente novo (Canguru, para os sócios).
insert into public.guides (agency_id, slug, title, audience, language, services, content, created_by)
values (1, 'onboarding', 'Como funciona o onboarding de cliente novo', 'socio', 'pt', '{}', '{"hero": {"eyebrow": "Bolsa · Onboarding de cliente novo", "title": "Do sim na proposta à campanha no ar, tudo num lugar só.", "text": "É assim que um cliente novo entra na Canguru e na Joey hoje. O cliente faz a parte dele pelo celular, no idioma dele. A equipe acompanha tudo num funil e o Claude monta a estratégia. Ninguém precisa pedir informação duas vezes nem caçar mensagem no WhatsApp."}, "steps": [{"title": "Proposta", "who": "Equipe", "tone": "equipe"}, {"title": "Cadastro", "who": "Cliente", "tone": "cliente"}, {"title": "Portal do começo", "who": "Cliente", "tone": "cliente"}, {"title": "Funil", "who": "Equipe", "tone": "equipe"}, {"title": "Estratégia", "who": "Equipe + Claude", "tone": "equipe"}, {"title": "Aprovação", "who": "Cliente", "tone": "cliente"}, {"title": "No ar", "who": "Equipe", "tone": "equipe"}], "sections": [{"who": "Equipe", "tone": "equipe", "title": "A proposta vira uma página, e a página vira o cadastro", "bullets": ["A equipe cola o resumo da reunião (ou um PDF) e o Claude escreve a proposta: o que entendemos, o trabalho, os primeiros passos e o investimento.", "O cliente recebe um link. A equipe vê quantas vezes ele abriu, por quanto tempo leu e se clicou para falar, e recebe um aviso no celular quando ele abre.", "No fim da página o cliente escolhe: Quero começar, que abre o cadastro já com o nome da empresa e marcado como trazido por quem fez a proposta, ou Falar no WhatsApp.", "Quando o cliente começa o cadastro, a proposta ganha o selo Fez o cadastro."], "images": [{"src": "/guias/onboarding/01-proposta.jpg", "alt": "Fim da página da proposta com os botões Quero começar e Falar no WhatsApp", "frame": "phone"}]}, {"who": "Cliente", "tone": "cliente", "layout": "stack", "title": "Cadastro em 5 passos, pelo celular, em uns 5 minutos", "text": "Cada pessoa da equipe tem o próprio link. O cliente fica marcado como trazido por ela e, no fim, o botão de contato abre o WhatsApp dela. O cadastro salva a cada passo: se o cliente parar no meio, a equipe vê no funil onde ele parou.", "cards": [{"title": "Idioma", "text": "Português, inglês ou espanhol. Na Joey, os valores aparecem em US$."}, {"title": "Dados", "text": "Nome, empresa, e-mail de acesso, WhatsApp, site e Instagram."}, {"title": "Negócio", "text": "Serviços contratados, o que vende, ticket, região, público, verba e o que já tentou."}, {"title": "Acessos", "text": "Passo a passo do Meta e do Google. Travou? Marca \"Preciso de ajuda\" e a equipe é avisada."}, {"title": "Termos", "text": "Termos do serviço com o nome da empresa e do responsável. Valores seguem a proposta."}, {"title": "Senha", "text": "Cria o login e entra direto no portal."}], "images": [{"src": "/guias/onboarding/02-cadastro-idioma.jpg", "alt": "Escolha de idioma do cadastro", "frame": "phone"}, {"src": "/guias/onboarding/03-cadastro-dados.jpg", "alt": "Passo 1 do cadastro: dados", "frame": "phone"}, {"src": "/guias/onboarding/04-cadastro-negocio.jpg", "alt": "Passo 2 do cadastro: negócio", "frame": "phone"}, {"src": "/guias/onboarding/05-cadastro-acessos.jpg", "alt": "Passo 3 do cadastro: acessos com passo a passo do Meta", "frame": "phone"}, {"src": "/guias/onboarding/06-cadastro-termos.jpg", "alt": "Passo 4 do cadastro: termos do serviço", "frame": "phone"}]}, {"who": "Cliente", "tone": "cliente", "layout": "image-left", "title": "O portal mostra onde estamos e o que falta", "bullets": ["Seis etapas sempre à vista: Cadastro, Briefing, Acessos, Estratégia, Aprovação e No ar.", "Um cartão escuro diz qual é o próximo passo do cliente, por exemplo responder o briefing de tráfego. São perguntas curtas, sem repetir o que ele já respondeu no cadastro.", "Os acessos ficam com o mesmo passo a passo do cadastro. Quando o cliente marca \"Já enviei\", a equipe confere e o selo muda para Conferido.", "Quando a estratégia fica pronta, o topo muda para \"Sua estratégia está pronta para você aprovar\"."], "images": [{"src": "/guias/onboarding/07-portal-cliente.jpg", "alt": "Portal do cliente com as etapas do começo do trabalho", "frame": "phone"}]}, {"who": "Equipe", "tone": "equipe", "layout": "stack", "dark": true, "title": "Um funil que diz o que a equipe precisa fazer agora", "text": "Em Comercial › Onboarding, cada cliente novo aparece numa coluna. As colunas mostram com quem está a bola. O menu ganha um número vermelho com quantos clientes estão esperando a equipe.", "bullets": ["No topo: quantos precisam da equipe, quantos estão com o cliente, quantos foram ao ar e a média de dias do cadastro ao ar.", "Cada cartão mostra o próximo passo: Gerar a estratégia, Ajudar com Google, Conferir acesso Meta, Ajustar a estratégia, Colocar a campanha no ar.", "Pedido de ajuda nos acessos vira um alerta amarelo com o nome do cliente.", "Ao abrir o cliente: tudo o que ele respondeu no cadastro e no briefing, os acessos, quem trouxe, e a estratégia com as versões."], "images": [{"src": "/guias/onboarding/12-funil.jpg", "alt": "Funil de novos clientes com o contador no menu, o resumo e o próximo passo no cartão", "frame": "browser"}]}, {"who": "Equipe + Claude", "tone": "equipe", "title": "O Claude monta a estratégia. A equipe revisa e envia.", "bullets": ["\"Gerar estratégia com o Claude\" lê o cadastro e o briefing e escreve o plano: objetivo, públicos, campanhas com a divisão da verba, o que os anúncios vão mostrar, como vamos medir e o caminho até o ar.", "Também lista os pontos em aberto só para a equipe, por exemplo um conflito entre o que o cliente disse no cadastro e no briefing.", "Precisa mudar? \"Pedir ajuste ao Claude\" com uma frase. Ele gera uma nova versão mudando só o que foi pedido, e as anteriores ficam guardadas.", "\"Copiar link e mensagem\" já prepara o texto para o WhatsApp do cliente."], "images": [{"src": "/guias/onboarding/13-ficha.jpg", "alt": "Ficha do cliente no funil: acessos conferidos e estratégia enviada", "frame": "browser"}]}, {"who": "Cliente", "tone": "cliente", "layout": "stack", "title": "O cliente lê, aprova ou pede ajuste pela própria página", "text": "A estratégia chega como uma página feita para o celular, escrita para o dono do negócio, sem jargão.", "bullets": ["A equipe vê no funil se ele abriu, quantas vezes e por quanto tempo leu.", "\"Quero ajustar algo\": o pedido cai no funil em amarelo e o Claude gera a versão seguinte a partir dele.", "O link é sempre o mesmo e mostra a versão mais recente.", "\"Aprovar estratégia\" registra quem aprovou e quando. O cartão vai para Subir campanha."], "images": [{"src": "/guias/onboarding/09-estrategia-topo.jpg", "alt": "Topo da página da estratégia", "frame": "phone"}, {"src": "/guias/onboarding/10-estrategia-verba.jpg", "alt": "Campanhas e divisão da verba na estratégia", "frame": "phone"}, {"src": "/guias/onboarding/11-estrategia-aprovar.jpg", "alt": "Botões para aprovar ou pedir ajuste", "frame": "phone"}]}, {"who": "Equipe", "tone": "equipe", "title": "Campanha no ar, cliente ativo", "text": "Com as campanhas configuradas, a equipe clica em \"Campanha no ar\". O cliente passa a ser ativo, o portal dele vira o portal normal (tráfego, conteúdo, relatórios) e o funil registra quantos dias levou do cadastro até o ar.", "cards": [{"title": "O cliente faz", "text": "Cadastro, briefing, acessos e aprovação. Tudo pelo celular, no idioma dele."}, {"title": "A equipe faz", "text": "Proposta, conferir acessos, revisar e enviar a estratégia e subir a campanha."}]}, {"kind": "note", "title": "O que ainda vem", "bullets": ["O contrato completo sair do cadastro (dados da empresa e valores da proposta), em vez do aceite de termos.", "Um caminho próprio para quem contrata só redes sociais. Hoje a estratégia é de tráfego.", "Endereço próprio para a Bolsa da Joey.", "E-mail de \"Esqueci minha senha\"."]}]}'::jsonb, '5f8f7e4c-aebc-494c-8377-ec05e467dee8')
